          category: "tech",
          description: "A clean dock for phone, earbuds, and watch in one place.",
          price: "$72",
          badge: "Top rated",
          rating: "4.8",
        },
      ];

      const dealProducts = [
        {
          name: "Stone Throw Blanket",
          description: "Layered warmth in a heavyweight weave.",
          price: "$64",
          oldPrice: "$89",
