          price: "$29",
          oldPrice: "$45",
        },
      ];

      const productGrid = document.getElementById("products-grid");
      const dealList = document.getElementById("deal-list");
      const filterButtons = document.querySelectorAll(".chip");

      function starRating(value) {
        return `★ ${value}`;
      }

      function productCard(product) {
        return `
          <article class="product-card" data-category="${product.category}">
            <div class="product-media">
              <div class="product-art" aria-hidden="true"></div>
            </div>
            <div class="product-body">
              <div class="meta-row">
                <span class="pill">${product.badge}</span>
                <span class="rating">${starRating(product.rating)}</span>
              </div>
              <h3>${product.name}</h3>
              <p>${product.description}</p>
              <div class="product-actions">
                <span class="price">${product.price}</span>
                <a class="link card-link" href="#">View details</a>
              </div>
            </div>
          </article>
        `;
      }

      function dealCard(product) {
        return `
          <article class="deal-card">
            <div class="deal-body">
              <div class="deal-row">
                <span class="pill">Deal</span>
                <span class="subtle"><s>${product.oldPrice}</s></span>
              </div>
              <h3>${product.name}</h3>
              <p>${product.description}</p>
              <div class="deal-row" style="margin-top: 0.95rem;">
                <span class="price">${product.price}</span>
                <a class="link card-link" href="#">Shop deal</a>
              </div>
            </div>
          </article>
        `;
      }

      function renderProducts(filter = "all") {
        const visible = filter === "all"
          ? products
          : products.filter((product) => product.category === filter);

        productGrid.innerHTML = visible.map(productCard).join("");
      }

      filterButtons.forEach((button) => {
        button.addEventListener("click", () => {
          const filter = button.dataset.filter;
          filterButtons.forEach((chip) => chip.setAttribute("aria-pressed", String(chip === button)));
          renderProducts(filter);
        });
      });

      dealList.innerHTML = dealProducts.map(dealCard).join("");
      renderProducts();

      const deadline = new Date(Date.now() + 1000 * 60 * 60 * 12 + 1000 * 60 * 24 + 1000 * 58);
      const hoursEl = document.getElementById("hours");
      const minutesEl = document.getElementById("minutes");
      const secondsEl = document.getElementById("seconds");

      function updateCountdown() {
        const remaining = Math.max(0, deadline - new Date());
        const totalSeconds = Math.floor(remaining / 1000);
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;

        hoursEl.textContent = String(hours).padStart(2, "0");
        minutesEl.textContent = String(minutes).padStart(2, "0");
        secondsEl.textContent = String(seconds).padStart(2, "0");
      }

      updateCountdown();
      setInterval(updateCountdown, 1000);
    </script>
