<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Northstar Retail | Home</title>
    <meta
      name="description"
      content="A polished dark ecommerce home page with featured products, deals, and editorial stories."
    />
    <style>
      :root {
        color-scheme: dark;
        --bg: #070b14;
        --bg-soft: #0d1320;
        --panel: rgba(14, 20, 33, 0.82);
        --panel-strong: #121a2c;
        --text: #f3f6fb;
        --muted: #a7b2c7;
        --line: rgba(255, 255, 255, 0.09);
        --accent: #7c5cff;
        --accent-2: #2dd4bf;
        --warm: #ffb86b;
        --success: #78f0a4;
        --shadow: 0 24px 60px rgba(0, 0, 0, 0.42);
        --radius-xl: 28px;
        --radius-lg: 22px;
        --radius-md: 16px;
        --radius-sm: 12px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
          sans-serif;
        background:
          radial-gradient(circle at top left, rgba(124, 92, 255, 0.2), transparent 30%),
          radial-gradient(circle at top right, rgba(45, 212, 191, 0.12), transparent 28%),
          linear-gradient(180deg, #050812 0%, #090d18 38%, #070b14 100%);
        color: var(--text);
        min-height: 100vh;
      }

      a {
        color: inherit;
        text-decoration: none;
      }

      img {
        max-width: 100%;
        display: block;
      }

      .skip-link {
        position: absolute;
        left: -999px;
        top: 12px;
        background: var(--accent);
        color: white;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        z-index: 100;
      }

      .skip-link:focus {
        left: 12px;
      }

      .shell {
        width: min(1200px, calc(100% - 2rem));
        margin: 0 auto;
      }

      .topbar {
        position: sticky;
        top: 0;
        z-index: 20;
        backdrop-filter: blur(16px);
        background: rgba(5, 8, 18, 0.72);
        border-bottom: 1px solid rgba(255, 255, 255, 0.06);
      }

      .nav {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        min-height: 76px;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        font-weight: 800;
        letter-spacing: 0.02em;
      }

      .brand-mark {
        width: 42px;
        height: 42px;
        display: grid;
        place-items: center;
        border-radius: 14px;
        background: linear-gradient(135deg, var(--accent), #4f8dff);
        box-shadow: 0 12px 24px rgba(124, 92, 255, 0.35);
      }

      .nav-links {
        display: flex;
        align-items: center;
        gap: 1.4rem;
        color: var(--muted);
      }

      .nav-links a:focus-visible,
      .btn:focus-visible,
      .card-link:focus-visible,
      .chip:focus-visible {
        outline: 2px solid var(--accent-2);
        outline-offset: 3px;
      }

      .nav-actions {
        display: flex;
        align-items: center;
        gap: 0.75rem;
      }

      .icon-btn,
      .btn,
      .chip {
        border: 0;
        border-radius: 999px;
        cursor: pointer;
        transition:
          transform 0.2s ease,
          background 0.2s ease,
          border-color 0.2s ease;
      }

      .icon-btn:hover,
      .btn:hover,
      .chip:hover {
        transform: translateY(-1px);
      }

      .icon-btn {
        width: 44px;
        height: 44px;
        background: rgba(255, 255, 255, 0.06);
        color: var(--text);
      }

      .btn {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.55rem;
        padding: 0.95rem 1.25rem;
        font-weight: 700;
        background: var(--accent);
        color: white;
        box-shadow: 0 16px 32px rgba(124, 92, 255, 0.28);
      }

      .btn.secondary {
        background: rgba(255, 255, 255, 0.07);
        color: var(--text);
        box-shadow: none;
      }

      .hero {
        padding: 3rem 0 2rem;
      }

      .hero-grid {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr;
        gap: 1.25rem;
      }

      .hero-copy,
      .hero-visual,
      .section-card,
      .product-card,
      .deal-card,
      .story-card,
      .metric-card {
        background: var(--panel);
        border: 1px solid var(--line);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow);
      }

      .hero-copy {
        padding: 2rem;
        overflow: hidden;
        position: relative;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.45rem 0.8rem;
        border-radius: 999px;
        background: rgba(124, 92, 255, 0.14);
        color: #d8ceff;
        font-size: 0.9rem;
        margin-bottom: 1.1rem;
      }

      h1,
      h2,
      h3,
      p {
        margin: 0;
      }

      h1 {
        font-size: clamp(2.5rem, 6vw, 5rem);
        line-height: 0.95;
        letter-spacing: -0.05em;
        max-width: 11ch;
      }

      .hero-copy p {
        margin-top: 1.1rem;
        max-width: 58ch;
        color: var(--muted);
        font-size: 1.03rem;
        line-height: 1.7;
      }

      .hero-cta {
        display: flex;
        flex-wrap: wrap;
        gap: 0.85rem;
        margin-top: 1.5rem;
      }

      .metric-row {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.9rem;
        margin-top: 1.8rem;
      }

      .metric-card {
        padding: 1rem;
        border-radius: var(--radius-lg);
      }

      .metric-value {
        display: block;
        font-size: 1.45rem;
        font-weight: 800;
      }

      .metric-label {
        display: block;
        margin-top: 0.3rem;
        color: var(--muted);
        font-size: 0.92rem;
      }

      .hero-visual {
        padding: 1.2rem;
        display: grid;
        gap: 1rem;
        align-content: start;
      }

      .glass-card {
        min-height: 270px;
        border-radius: calc(var(--radius-xl) - 4px);
        background:
          linear-gradient(160deg, rgba(124, 92, 255, 0.25), rgba(45, 212, 191, 0.06)),
          linear-gradient(180deg, rgba(18, 26, 44, 0.8), rgba(10, 14, 24, 0.85));
        border: 1px solid rgba(255, 255, 255, 0.08);
        position: relative;
        overflow: hidden;
        padding: 1.25rem;
      }

      .floating-tag {
        position: absolute;
        padding: 0.55rem 0.75rem;
        border-radius: 999px;
        background: rgba(7, 11, 20, 0.72);
        border: 1px solid rgba(255, 255, 255, 0.08);
        font-size: 0.88rem;
      }

      .tag-1 {
        top: 1rem;
        right: 1rem;
      }

      .tag-2 {
        left: 1rem;
        bottom: 1rem;
      }

      .mock-product {
        width: min(76%, 340px);
        aspect-ratio: 1;
        border-radius: 28px;
        margin: 3rem auto 0;
        background:
          radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.28), transparent 22%),
          linear-gradient(160deg, #1c2540, #0b1020 58%, #111a31);
        box-shadow:
          inset 0 1px 0 rgba(255, 255, 255, 0.08),
          0 24px 64px rgba(0, 0, 0, 0.35);
        display: grid;
        place-items: center;
      }

      .mock-product::before {
        content: "";
        width: 58%;
        aspect-ratio: 0.82;
        border-radius: 32px;
        background:
          linear-gradient(180deg, rgba(255, 255, 255, 0.12), transparent),
          linear-gradient(135deg, #2dd4bf, #7c5cff 58%, #f0b56d);
        clip-path: polygon(22% 0, 78% 0, 100% 34%, 81% 100%, 19% 100%, 0 34%);
        filter: drop-shadow(0 20px 30px rgba(0, 0, 0, 0.28));
      }

      .section {
        padding: 1.1rem 0 3rem;
      }

      .section-header {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1rem;
      }

      .section-header p {
        color: var(--muted);
        margin-top: 0.35rem;
      }

      .section-card {
        padding: 1.25rem;
      }

      .chips {
        display: flex;
        gap: 0.65rem;
        flex-wrap: wrap;
      }

      .chip {
        padding: 0.75rem 1rem;
        background: rgba(255, 255, 255, 0.06);
        color: var(--text);
        border: 1px solid transparent;
      }

      .chip[aria-pressed="true"] {
        background: rgba(124, 92, 255, 0.18);
        border-color: rgba(124, 92, 255, 0.4);
      }

      .grid {
        display: grid;
        gap: 1rem;
      }

      .products-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .products-grid.compact {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .product-card,
      .deal-card,
      .story-card {
        overflow: hidden;
      }

      .product-media,
      .story-media {
        min-height: 210px;
        position: relative;
        display: grid;
        place-items: center;
        background: linear-gradient(160deg, rgba(124, 92, 255, 0.13), rgba(45, 212, 191, 0.06));
      }

      .product-media::after,
      .story-media::after {
        content: "";
        position: absolute;
        inset: 18px;
        border-radius: 22px;
        border: 1px solid rgba(255, 255, 255, 0.08);
      }

      .product-art {
        width: 62%;
        aspect-ratio: 1;
        border-radius: 24px;
        background: linear-gradient(145deg, #18213a, #0f1526 65%, #1b2948);
        position: relative;
      }

      .product-art::before {
        content: "";
        position: absolute;
        inset: 18%;
        border-radius: 18px;
        background:
          radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.2), transparent 18%),
          linear-gradient(135deg, rgba(124, 92, 255, 0.85), rgba(45, 212, 191, 0.7));
      }

      .product-body,
      .deal-body,
      .story-body {
        padding: 1rem;
      }

      .meta-row,
      .deal-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
      }

      .meta-row {
        margin-bottom: 0.6rem;
      }

      .pill {
        display: inline-flex;
        align-items: center;
        gap: 0.35rem;
        padding: 0.35rem 0.65rem;
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.06);
        color: var(--muted);
        font-size: 0.82rem;
      }

      .rating {
        color: #ffd166;
        font-size: 0.92rem;
      }

      .price {
        font-weight: 800;
        font-size: 1.15rem;
      }

      .subtle {
        color: var(--muted);
      }

      .product-body h3,
      .deal-body h3,
      .story-body h3 {
        font-size: 1.05rem;
        line-height: 1.35;
        margin-bottom: 0.4rem;
      }

      .product-body p,
      .deal-body p,
      .story-body p {
        color: var(--muted);
        line-height: 1.65;
        font-size: 0.95rem;
      }

      .product-actions,
      .story-actions {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
        margin-top: 1rem;
      }

      .link {
        color: #d9d0ff;
        font-weight: 700;
      }

      .deal-layout {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr;
        gap: 1rem;
      }

      .deal-card {
        background: linear-gradient(180deg, rgba(18, 26, 44, 0.94), rgba(10, 14, 24, 0.98));
      }

      .deal-card.featured {
        padding: 1.25rem;
        background:
          radial-gradient(circle at top right, rgba(255, 184, 107, 0.15), transparent 28%),
          linear-gradient(180deg, rgba(18, 26, 44, 0.94), rgba(10, 14, 24, 0.98));
      }

      .deal-banner {
        min-height: 100%;
        border-radius: calc(var(--radius-xl) - 8px);
        background:
          radial-gradient(circle at 20% 20%, rgba(255, 184, 107, 0.35), transparent 24%),
          linear-gradient(140deg, rgba(124, 92, 255, 0.9), rgba(9, 13, 24, 0.1) 60%),
          linear-gradient(180deg, #121a2c, #0a0e18);
        padding: 1.25rem;
        position: relative;
        overflow: hidden;
      }

      .deal-banner::before {
        content: "";
        position: absolute;
        inset: auto -10% -24% auto;
        width: 220px;
        aspect-ratio: 1;
        border-radius: 50%;
        background: rgba(45, 212, 191, 0.18);
        filter: blur(6px);
      }

      .countdown {
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 0.6rem;
        margin-top: 1.2rem;
      }

      .time-box {
        padding: 0.85rem;
        border-radius: 16px;
        background: rgba(255, 255, 255, 0.07);
        text-align: center;
      }

      .time-box strong {
        display: block;
        font-size: 1.2rem;
      }

      .time-box span {
        display: block;
        margin-top: 0.18rem;
        color: var(--muted);
        font-size: 0.8rem;
      }

      .story-grid {
        grid-template-columns: 1.1fr 0.9fr 0.9fr;
      }

      .story-media {
        min-height: 180px;
      }

      .story-visual {
        width: 72%;
        height: 72%;
        border-radius: 28px;
        background: linear-gradient(135deg, rgba(45, 212, 191, 0.85), rgba(124, 92, 255, 0.78));
        transform: rotate(-8deg);
      }

      .story-visual.alt {
        background: linear-gradient(135deg, rgba(255, 184, 107, 0.82), rgba(124, 92, 255, 0.72));
      }

      .story-visual.third {
        background: linear-gradient(135deg, rgba(255, 255, 255, 0.16), rgba(45, 212, 191, 0.72));
      }

      .footer {
        padding: 1rem 0 2.5rem;
        color: var(--muted);
      }

      .footer-inner {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        padding-top: 1rem;
        border-top: 1px solid rgba(255, 255, 255, 0.08);
        flex-wrap: wrap;
      }

      @media (max-width: 1024px) {
        .hero-grid,
        .deal-layout,
        .story-grid {
          grid-template-columns: 1fr;
        }

        .products-grid,
        .products-grid.compact {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }

      @media (max-width: 720px) {
        .nav {
          flex-wrap: wrap;
          padding: 0.75rem 0;
        }

        .nav-links {
          width: 100%;
          justify-content: space-between;
          order: 3;
          padding-top: 0.25rem;
          overflow-x: auto;
        }

        .hero {
          padding-top: 1.5rem;
        }

        .hero-copy,
        .hero-visual,
        .section-card {
          padding: 1.1rem;
        }

        h1 {
          max-width: 12ch;
        }

        .metric-row,
        .products-grid,
        .products-grid.compact,
        .countdown {
          grid-template-columns: 1fr;
        }

        .section-header {
          align-items: start;
          flex-direction: column;
        }

        .nav-links {
          gap: 1rem;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to content</a>

    <header class="topbar">
      <div class="shell nav">
        <a class="brand" href="#main-content" aria-label="Northstar Retail home">
          <span class="brand-mark" aria-hidden="true">N</span>
          <span>Northstar Retail</span>
        </a>

        <nav class="nav-links" aria-label="Site">
          <a href="#featured">Featured</a>
          <a href="#deals">Deals</a>
          <a href="#editorial">Editorial</a>
        </nav>

        <div class="nav-actions">
          <button class="icon-btn" type="button" aria-label="Search">
            ⌕
          </button>
          <button class="icon-btn" type="button" aria-label="Open cart">
            🛍
          </button>
          <a class="btn secondary" href="#featured">Shop now</a>
        </div>
      </div>
    </header>

    <main id="main-content">
      <section class="hero">
        <div class="shell hero-grid">
          <article class="hero-copy">
            <span class="eyebrow">New season / curated essentials</span>
            <h1>Modern retail for every day rituals.</h1>
            <p>
              Discover elevated home, style, and tech pieces selected to feel premium,
              practical, and easy to shop. Built for fast browsing and confident decisions.
            </p>

            <div class="hero-cta">
              <a class="btn" href="#featured">Explore featured products</a>
              <a class="btn secondary" href="#editorial">Read the edit</a>
            </div>

            <div class="metric-row" aria-label="Store highlights">
              <div class="metric-card">
                <span class="metric-value">250+</span>
                <span class="metric-label">New arrivals this month</span>
              </div>
              <div class="metric-card">
                <span class="metric-value">4.9/5</span>
                <span class="metric-label">Average customer rating</span>
              </div>
              <div class="metric-card">
                <span class="metric-value">48h</span>
                <span class="metric-label">Fast shipping on top sellers</span>
              </div>
            </div>
          </article>

          <aside class="hero-visual" aria-label="Featured product preview">
            <div class="glass-card">
              <span class="floating-tag tag-1">Bestseller</span>
              <span class="floating-tag tag-2">Free returns</span>
              <div class="mock-product" aria-hidden="true"></div>
            </div>
          </aside>
        </div>
      </section>

      <section class="section" id="featured">
        <div class="shell section-card">
          <div class="section-header">
            <div>
              <h2>Featured products</h2>
              <p>Editor-approved picks across home, wardrobe, and everyday carry.</p>
            </div>
            <div class="chips" role="toolbar" aria-label="Featured filters">
              <button class="chip" type="button" aria-pressed="true" data-filter="all">All</button>
              <button class="chip" type="button" aria-pressed="false" data-filter="home">Home</button>
              <button class="chip" type="button" aria-pressed="false" data-filter="style">Style</button>
              <button class="chip" type="button" aria-pressed="false" data-filter="tech">Tech</button>
            </div>
          </div>

          <div class="grid products-grid" id="products-grid" aria-live="polite"></div>
        </div>
      </section>

      <section class="section" id="deals">
        <div class="shell deal-layout">
          <article class="deal-card featured">
            <div class="deal-banner">
              <span class="eyebrow">Today only / limited stock</span>
              <h2 style="font-size: clamp(1.8rem, 4vw, 3rem); line-height: 1.02; max-width: 12ch">
                Midnight drop: up to 40% off statement essentials.
              </h2>
              <p style="margin-top: 0.9rem; max-width: 46ch; color: var(--muted); line-height: 1.7">
                Bundle top-rated pieces and save on the products customers keep coming back for.
              </p>

              <div class="countdown" aria-label="Deal countdown">
                <div class="time-box"><strong id="hours">12</strong><span>Hours</span></div>
                <div class="time-box"><strong id="minutes">24</strong><span>Minutes</span></div>
                <div class="time-box"><strong id="seconds">58</strong><span>Seconds</span></div>
                <div class="time-box"><strong>40%</strong><span>Off</span></div>
              </div>
            </div>
          </article>

          <aside class="grid" id="deal-list" aria-label="Deal products"></aside>
        </div>
      </section>

      <section class="section" id="editorial">
