                <a class="link card-link" href="#deals">Shop deal</a>
              </div>
            </div>
          </article>
        `;
      }

      function renderProducts(filter = "all") {
        const visible = filter === "all"
          ? products
          : products.filter((product) => product.category === filter);

        productGrid.innerHTML = visible.map(productCard).join("");
      }

      filterButtons.forEach((button) => {
        button.addEventListener("click", () => {
          const filter = button.dataset.filter;
          filterButtons.forEach((chip) => chip.setAttribute("aria-pressed", String(chip === button)));
          renderProducts(filter);
        });
      });

      dealList.innerHTML = dealProducts.map(dealCard).join("");
      renderProducts();

      const deadline = new Date(Date.now() + 1000 * 60 * 60 * 12 + 1000 * 60 * 24 + 1000 * 58);
      const hoursEl = document.getElementById("hours");
      const minutesEl = document.getElementById("minutes");
      const secondsEl = document.getElementById("seconds");

      function updateCountdown() {
        const remaining = Math.max(0, deadline - new Date());
        const totalSeconds = Math.floor(remaining / 1000);
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;

        hoursEl.textContent = String(hours).padStart(2, "0");
        minutesEl.textContent = String(minutes).padStart(2, "0");
        secondsEl.textContent = String(seconds).padStart(2, "0");
      }

      updateCountdown();
      setInterval(updateCountdown, 1000);
