    </header>

    <main id="main-content">
      <section class="hero">
        <div class="shell hero-grid">
          <article class="hero-copy">
            <span class="eyebrow">New season / curated essentials</span>
            <h1>Modern retail for every day rituals.</h1>
            <p>
              Discover elevated home, style, and tech pieces selected to feel premium,
              practical, and easy to shop. Built for fast browsing and confident decisions.
            </p>

            <div class="hero-cta">
              <a class="btn" href="#featured">Explore featured products</a>
              <a class="btn secondary" href="#editorial">Read the edit</a>
            </div>

            <div class="metric-row" aria-label="Store highlights">
              <div class="metric-card">
                <span class="metric-value">250+</span>
                <span class="metric-label">New arrivals this month</span>
              </div>
              <div class="metric-card">
                <span class="metric-value">4.9/5</span>
                <span class="metric-label">Average customer rating</span>
              </div>
              <div class="metric-card">
                <span class="metric-value">48h</span>
                <span class="metric-label">Fast shipping on top sellers</span>
              </div>
            </div>
          </article>

          <aside class="hero-visual" aria-label="Featured product preview">
            <div class="glass-card">
              <span class="floating-tag tag-1">Bestseller</span>
              <span class="floating-tag tag-2">Free returns</span>
              <div class="mock-product" aria-hidden="true"></div>
            </div>
          </aside>
        </div>
      </section>

      <section class="section" id="featured">
        <div class="shell section-card">
          <div class="section-header">
            <div>
              <h2>Featured products</h2>
              <p>Editor-approved picks across home, wardrobe, and everyday carry.</p>
            </div>
            <div class="chips" role="toolbar" aria-label="Featured filters">
              <button class="chip" type="button" aria-pressed="true" data-filter="all">All</button>
              <button class="chip" type="button" aria-pressed="false" data-filter="home">Home</button>
              <button class="chip" type="button" aria-pressed="false" data-filter="style">Style</button>
              <button class="chip" type="button" aria-pressed="false" data-filter="tech">Tech</button>
            </div>
          </div>

          <div class="grid products-grid" id="products-grid" aria-live="polite"></div>
        </div>
      </section>

      <section class="section" id="deals">
        <div class="shell deal-layout">
          <article class="deal-card featured">
            <div class="deal-banner">
              <span class="eyebrow">Today only / limited stock</span>
              <h2 style="font-size: clamp(1.8rem, 4vw, 3rem); line-height: 1.02; max-width: 12ch">
                Midnight drop: up to 40% off statement essentials.
              </h2>
              <p style="margin-top: 0.9rem; max-width: 46ch; color: var(--muted); line-height: 1.7">
                Bundle top-rated pieces and save on the products customers keep coming back for.
              </p>

              <div class="countdown" aria-label="Deal countdown">
                <div class="time-box"><strong id="hours">12</strong><span>Hours</span></div>
                <div class="time-box"><strong id="minutes">24</strong><span>Minutes</span></div>
                <div class="time-box"><strong id="seconds">58</strong><span>Seconds</span></div>
                <div class="time-box"><strong>40%</strong><span>Off</span></div>
              </div>
            </div>
          </article>

          <aside class="grid" id="deal-list" aria-label="Deal products"></aside>
        </div>
      </section>

      <section class="section" id="editorial">
        <div class="shell section-card">
          <div class="section-header">
            <div>
              <h2>Editorial content</h2>
              <p>Style notes and shopping ideas from the Northstar team.</p>
            </div>
          </div>

          <div class="grid story-grid">
            <article class="story-card">
              <div class="story-media">
                <div class="story-visual" aria-hidden="true"></div>
              </div>
              <div class="story-body">
                <span class="pill">Style guide</span>
                <h3>How to build a capsule collection that feels expensive.</h3>
                <p>
                  Focus on a clean palette, tactile materials, and one standout accessory to
                  elevate every outfit.
                </p>
                <div class="story-actions">
                  <a class="link" href="#editorial">Read story</a>
                  <span class="subtle">6 min read</span>
                </div>
              </div>
            </article>

            <article class="story-card">
              <div class="story-media">
                <div class="story-visual alt" aria-hidden="true"></div>
              </div>
              <div class="story-body">
                <span class="pill">Home edit</span>
                <h3>Small-space upgrades that instantly make a room feel calmer.</h3>
                <p>
                  Layer lighting, add concealed storage, and choose one sculptural object to
                  anchor the room.
                </p>
                <div class="story-actions">
                  <a class="link" href="#editorial">Read story</a>
                  <span class="subtle">4 min read</span>
                </div>
              </div>
            </article>

            <article class="story-card">
              <div class="story-media">
                <div class="story-visual third" aria-hidden="true"></div>
              </div>
              <div class="story-body">
                <span class="pill">Gift guide</span>
                <h3>Useful gifts that still feel personal and premium.</h3>
                <p>
                  A fast list for birthdays, thank-yous, and last-minute finds that never feel
                  generic.
                </p>
                <div class="story-actions">
                  <a class="link" href="#editorial">Read story</a>
                  <span class="subtle">3 min read</span>
                </div>
              </div>
            </article>
          </div>
        </div>
      </section>
    </main>

    <footer class="footer">
      <div class="shell footer-inner">
        <span>Northstar Retail</span>
        <span>Curated essentials for modern living</span>
      </div>
    </footer>

    <script>
      const products = [
        {
          name: "Lumen Table Lamp",
          category: "home",
          description: "Soft ambient light with a brushed finish and touch dimmer.",
          price: "$89",
          badge: "Best seller",
          rating: "4.9",
        },
        {
          name: "Aero Knit Jacket",
          category: "style",
          description: "Lightweight layering piece designed for all-day comfort.",
          price: "$124",
          badge: "New",
          rating: "4.8",
        },
        {
          name: "Arc Speaker Mini",
          category: "tech",
          description: "Compact sound with crisp highs and a rich low end.",
          price: "$149",
          badge: "Wireless",
          rating: "4.7",
        },
        {
          name: "Marble Tray Set",
          category: "home",
          description: "Organize daily essentials with a sculptural surface.",
          price: "$58",
          badge: "Limited",
          rating: "5.0",
        },
        {
          name: "Transit Day Pack",
          category: "style",
          description: "Streamlined carry with laptop protection and hidden pockets.",
          price: "$96",
          badge: "Travel",
          rating: "4.9",
        },
        {
          name: "Pulse Charging Dock",
          category: "tech",
          description: "A clean dock for phone, earbuds, and watch in one place.",
          price: "$72",
          badge: "Top rated",
          rating: "4.8",
        },
      ];

      const dealProducts = [
        {
          name: "Stone Throw Blanket",
          description: "Layered warmth in a heavyweight weave.",
          price: "$64",
          oldPrice: "$89",
        },
        {
          name: "Studio Glass Set",
          description: "A clean four-piece set for everyday entertaining.",
          price: "$39",
          oldPrice: "$54",
        },
        {
          name: "Contour Desk Mat",
          description: "Soft support and a matte finish for workspaces.",
          price: "$29",
          oldPrice: "$45",
        },
      ];

      const productGrid = document.getElementById("products-grid");
      const dealList = document.getElementById("deal-list");
      const filterButtons = document.querySelectorAll(".chip");

      function starRating(value) {
        return `★ ${value}`;
      }

      function productCard(product) {
        return `
          <article class="product-card" data-category="${product.category}">
            <div class="product-media">
              <div class="product-art" aria-hidden="true"></div>
            </div>
            <div class="product-body">
              <div class="meta-row">
                <span class="pill">${product.badge}</span>
                <span class="rating">${starRating(product.rating)}</span>
              </div>
              <h3>${product.name}</h3>
              <p>${product.description}</p>
              <div class="product-actions">
                <span class="price">${product.price}</span>
                <a class="link card-link" href="#featured">View details</a>
              </div>
            </div>
          </article>
        `;
      }

      function dealCard(product) {
        return `
          <article class="deal-card">
            <div class="deal-body">
              <div class="deal-row">
                <span class="pill">Deal</span>
                <span class="subtle"><s>${product.oldPrice}</s></span>
              </div>
              <h3>${product.name}</h3>
              <p>${product.description}</p>
              <div class="deal-row" style="margin-top: 0.95rem;">
                <span class="price">${product.price}</span>
                <a class="link card-link" href="#deals">Shop deal</a>
              </div>
            </div>
          </article>
        `;
      }

      function renderProducts(filter = "all") {
        const visible = filter === "all"
          ? products
          : products.filter((product) => product.category === filter);

        productGrid.innerHTML = visible.map(productCard).join("");
      }

      filterButtons.forEach((button) => {
        button.addEventListener("click", () => {
          const filter = button.dataset.filter;
          filterButtons.forEach((chip) => chip.setAttribute("aria-pressed", String(chip === button)));
          renderProducts(filter);
        });
      });

      dealList.innerHTML = dealProducts.map(dealCard).join("");
      renderProducts();

      const deadline = new Date(Date.now() + 1000 * 60 * 60 * 12 + 1000 * 60 * 24 + 1000 * 58);
      const hoursEl = document.getElementById("hours");
      const minutesEl = document.getElementById("minutes");
      const secondsEl = document.getElementById("seconds");

      function updateCountdown() {
        const remaining = Math.max(0, deadline - new Date());
        const totalSeconds = Math.floor(remaining / 1000);
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;

        hoursEl.textContent = String(hours).padStart(2, "0");
        minutesEl.textContent = String(minutes).padStart(2, "0");
        secondsEl.textContent = String(seconds).padStart(2, "0");
      }

      updateCountdown();
      setInterval(updateCountdown, 1000);
    </script>
  </body>
</html>
